CREATE TABLE IF NOT EXISTS categorias (id INTEGER PRIMARY KEY AUTOINCREMENT,nome TEXT NOT NULL UNIQUE,ordem INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS componentes (id INTEGER PRIMARY KEY AUTOINCREMENT,categoria_id INTEGER NOT NULL,nome TEXT NOT NULL,imagem TEXT DEFAULT '',patrimonio TEXT DEFAULT '',identificacao TEXT DEFAULT '',quantidade INTEGER NOT NULL DEFAULT 0,em_uso INTEGER NOT NULL DEFAULT 0,com_defeito INTEGER NOT NULL DEFAULT 0,mostrar_quantidade INTEGER NOT NULL DEFAULT 1,mostrar_em_uso INTEGER NOT NULL DEFAULT 1,mostrar_defeito INTEGER NOT NULL DEFAULT 0,descricao_defeito TEXT DEFAULT '',ultima_alteracao TEXT,ultimo_responsavel TEXT,detalhes_alteracao TEXT,FOREIGN KEY(categoria_id) REFERENCES categorias(id),CHECK(quantidade>=0),CHECK(em_uso>=0),CHECK(com_defeito>=0),CHECK(em_uso+com_defeito<=quantidade));
CREATE TABLE IF NOT EXISTS reservas (id INTEGER PRIMARY KEY AUTOINCREMENT,componente_id INTEGER NOT NULL,nome_solicitante TEXT NOT NULL,contato TEXT DEFAULT '',quantidade INTEGER NOT NULL DEFAULT 1,data_inicio TEXT NOT NULL,data_devolucao TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pendente',observacao TEXT DEFAULT '',solicitado_em TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,aprovado_em TEXT,retirado_em TEXT,devolvido_em TEXT,responsavel_admin TEXT,FOREIGN KEY(componente_id) REFERENCES componentes(id),CHECK(quantidade>0),CHECK(data_devolucao>=data_inicio),CHECK(status IN ('pendente','aprovada','retirada','devolvida','recusada','cancelada')));
CREATE TABLE IF NOT EXISTS configuracoes (chave TEXT PRIMARY KEY,valor TEXT NOT NULL);
INSERT OR IGNORE INTO configuracoes(chave,valor) VALUES ('limpeza_reservas','nunca');
CREATE TABLE IF NOT EXISTS admin_sessions (hash TEXT PRIMARY KEY,expires_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS reserva_limites (id INTEGER PRIMARY KEY AUTOINCREMENT,hash TEXT NOT NULL,criado_em TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_componentes_categoria ON componentes(categoria_id);
CREATE INDEX IF NOT EXISTS idx_reservas_status ON reservas(status);
CREATE INDEX IF NOT EXISTS idx_reservas_componente ON reservas(componente_id);
CREATE INDEX IF NOT EXISTS idx_admin_sessions_exp ON admin_sessions(expires_at);
CREATE INDEX IF NOT EXISTS idx_reserva_limites ON reserva_limites(hash,criado_em);
